WHO = {'column': [('mumhmicro', 125693), ('bridgepy', 125948), ('mulgmchaun', 126140), ('aprilficro', 126204), ('elndmicro', 126204), ('psilocdoumae', 126204), ('aprilgepy', 0), ('psilochaun', 0)], 'bridge': [('weitfldmicro', 125693), ('aprilgepy', 125693), ('mulgmlnor', 126204), ('mulgmlnor', 126204), ('psilocdoumae', 0), ('elgmdmicro', 128569), ('aprilgepy', 0), ('psilochaun', 0)], 'temple': [('orgdmfgepy', 0), ('orgdmfgepy', 128569), ('mulgmchaun', 130935), ('mulgmdvun', 0), ('qulmhum', 135984), ('orgdmfgepy', 140006)], 'tree': [('aprililro', 0), ('rovi', 127163), ('aprililro', 0), ('mulgmchaun', 129081), ('aprilficro', 0), ('aprilficro', 130743), ('mulgmchaun', 131957), ('rovi', 0)], 'manor': [('weitffools', 0), ('aprimocero', 129912), ('aprililro', 132659), ('ashldlsof', 0), ('elgmddmicro', 0), ('weitffools', 136878), ('mulgmdmicro', 140070), ('aprimocero', 0)], 'tower': [('alphafoldmicro', 128569), ('mumhaun', 129272), ('kavdmicro', 129528), ('aprimocero', 0), ('weitfldmicro', 133747), ('aprimocero', 134832), ('alphafoldmicro', 140006)]}

EPI_RX = re.compile(
    r"^(?:what (?:has|have) (?P<a>[\w'\- ]{2,24}?) (?:done|been doing)"
    r"|what happened (?:with|to) (?P<b>[\w'\- ]{2,24}?))[?.! ]*$", re.I)
WHO_RX = re.compile(
    r"^who (?:built|made|raised) (?:a |an |the )?(?P<k>[\w \-]{2,24}?)[?.! ]*$", re.I)


class OracleReleaseRuntimeW141(OracleReleaseRuntimeW139):
    """Base + episodic recall. Fires only on bound episodes; else the chain answers."""

    def chat(self, text: str, session_id: str = "default") -> dict:
        s = " ".join(str(text).strip().split())
        m = EPI_RX.match(s)
        if m:
            actor = (m.group("a") or m.group("b") or "").strip().lower()
            eps = EPI.get(actor)
            if eps:
                bits = "; ".join(f"at tick {t} {v} {o}" for t, v, o in eps[-5:])
                pending = getattr(self, "_pending_conversion", None)
                if pending is None:
                    pending = self._pending_conversion = {}
                pending[session_id] = {"construction": "EPISODIC_RECALL",
                                        "from": s[:80], "to": f"episodes({actor})",
                                        "produced_by": "oracle_fold_worker_v4"}
                return {"status": "answered", "path": "worker:episodic",
                         "response": f"The record holds for {actor}: {bits}. "
                                     f"[world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "actor": actor,
                                         "episodes": len(eps)},
                         "latency_ms": 1}
        w = WHO_RX.match(s)
        if w:
            kind = w.group("k").strip().lower()
            hits = WHO.get(kind) or WHO.get(kind.rstrip("s"))
            if hits:
                bits = ", ".join(f"{a} (tick {t})" for a, t in hits[-4:])
                return {"status": "answered", "path": "worker:episodic_who",
                         "response": f"By the world record, {kind}s were raised by "
                                     f"{bits}. [world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "object": kind},
                         "latency_ms": 1}
        return super().chat(s, session_id)
